package com.codeguardian.controller; import com.codeguardian.dto.*; import com.codeguardian.service.CicdService; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/cicd") @RequiredArgsConstructor public class CicdController{private final CicdService service;@PostMapping("/reviews")public ResponseEntity<ReviewResponseDTO> trigger(@RequestBody ReviewRequestDTO r){return ResponseEntity.accepted().body(service.trigger(r));}@GetMapping("/reviews/{id}/quality-gate")public Map<String,Object> gate(@PathVariable Long id){return service.qualityGate(id);}@PostMapping("/webhooks/git")public ResponseEntity<Void> webhook(@RequestBody Map<String,Object> payload){service.handleWebhook(payload);return ResponseEntity.accepted().build();}}
